import{z as d,x as s,o as E,c as p,q as t,j as r,D as a,d as l,s as o,S as A,b as i}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"多模态编码器流水","description":"","frontmatter":{"title":"多模态编码器流水","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vision-encoder-pipeline.md","filePath":"llm/vision-encoder-pipeline.md","lastUpdated":1791063341000}'),B={name:"llm/vision-encoder-pipeline.md"};function L(m,e,f,T,_,c){const n=s("Mermaid");return E(),p("div",null,[e[2]||(e[2]=t('<h1 id="多模态编码器流水" tabindex="-1">多模态编码器流水 <a class="header-anchor" href="#多模态编码器流水" aria-label="Permalink to &quot;多模态编码器流水&quot;">​</a></h1><div class="epigraph"><p>图像先被视觉编码器变成一串 token，再与文本一起做语言模型 prefill；两段的屋顶不同，串行等待会把首 token 延迟写成两者之和。</p><footer>—— Radford et al., CLIP；视觉指令对齐见 Liu et al., LLaVA；服务上把编码器与 LLM 分阶段调度</footer></div><p><a href="/llm/tokenizer-parallel">上一课</a>把文本 id 并行化。多模态请求还要跑 ViT / 音频编码器。CLIP 把图像编进与文本对齐的空间；LLaVA 一类把视觉 token 投进 LLM 的 embedding 维。本课写 <em>流水</em>：编码器是算力密、形状由分辨率决定；LLM prefill 吃视觉 token 长度 \\(n_v\\) 加文本。串行则 TTFT \\(=T_{\\mathrm{enc}}+T_{\\mathrm{prefill}}\\)；重叠与连续批要把编码器当成另一类 prefill 池。不重写连接器结构，见主干视觉课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n_v\\) 随分辨率与 patch 走，可以比文本提示还长，直接打进<a href="/llm/long-context-memory-curve">长上下文曲线</a>的 KV 与二次项。编码器本身不写 LLM 的 KV，但占用 GPU。若与 decode 混在同一张卡，正在吐词的用户被一张图的 ViT 挡住。缺口是阶段拆分：视觉编码、投影、LLM prefill、decode 是否同池，以及编码器批处理（多张图拼 batch）如何与变长 \\(n_v\\) 共存。</p><p><span class="marginnote">术语翻译：ViT（视觉 Transformer）把图像切成 14×14 或 16×16 像素的小块（patch），每块当一个「视觉词」编码；\\(n_v\\) 就是这张图最终变成多少个视觉词。512×512 的图按 14×14 切约有 1300 块——比大多数文本提示还长，这就是它吃 KV 的原因。</span></p><p>动态分辨率（AnyRes、切块）让 \\(n_v\\) 请求间不同，连续批更难。会计必须用实际 \\(n_v\\)，不能用「一张图 = 256 token」的旧默认。</p><p><span class="marginnote">视觉 token 的 KV 在 LLM 侧与文本 KV 同公式。减 \\(n_v\\)（池化、压缩）是容量优化，与 CLIP 质量权衡，不是本课的核融合细节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>独立编码器流或独立池：图在编码器上跑时，文本分词与系统前缀 KV 可并行准备。编码器输出再投影，插入 LLM prefill。连续批：编码器按图像批，LLM 按 token 批，中间有队列。失败回退：编码失败不应占着 LLM 槽。投机对视觉前缀通常只在文本生成段，视觉段是 prefill，投机收益小。</p><p>与 <a href="/llm/flashattention">FlashAttention</a>：LLM prefill 的 \\(n=n_v+n_{\\text{text}}\\)，二次项主要来自视觉。压缩 \\(n_v\\) 对 TTFT 的导数往往大于再调 LLM 核。</p><p><span class="marginnote">数字实例：\\(n_v=1000\\)、文本 100 时，prefill 序列 \\(n=1100\\)，二次注意力项约 \\(1.2\\times10^6\\)；把视觉 token 压到 250，序列 350，二次项降到约 \\(1.2\\times10^5\\)——降了近一个数量级。这就是「压缩 \\(n_v\\) 的收益大于再调 LLM 内核」的量级感受。</span></p>',12)),(E(),r(A,null,{default:a(()=>[o(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20ENC%5B%22%E8%A7%86%E8%A7%89%E7%BC%96%E7%A0%81%E5%99%A8%E6%B1%A0%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20TOK%5B%22%E5%88%86%E8%AF%8D%22%5D%0A%20%20ENC%20--%3E%20PRJ%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%20LLM%20%E7%BB%B4%22%5D%0A%20%20TOK%20--%3E%20PRE%5B%22LLM%20prefill%22%5D%0A%20%20PRJ%20--%3E%20PRE%0A%20%20PRE%20--%3E%20DEC%5B%22%E6%96%87%E6%9C%AC%20decode%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i("h2",{id:"机制",tabindex:"-1"},[l("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=i("p",null,"两段屋顶：ViT 像训练时的视觉骨干，算力绑定；随后 LLM prefill 也算力绑定，但形状是序列。拆池是为了别让 decode 带宽型工作与 ViT 抢 SM。成本模型应分列「每图编码」与「每视觉 token 的 LLM prefill」，否则定价只按输出字会亏在高分辨率上。",-1)),(E(),r(A,null,{default:a(()=>[o(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E5%A4%9A%E6%A8%A1%E6%80%81%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20S%7B%22%E7%BC%96%E7%A0%81%E5%99%A8%E4%B8%8E%20LLM%20%E6%98%AF%E5%90%A6%E5%88%86%E6%B1%A0%3F%22%7D%0A%20%20S%20--%3E%7C%22%E5%90%8C%E6%B1%A0%E4%B8%B2%E8%A1%8C%22%7C%20SER%5B%22TTFT%20%3D%20%E7%BC%96%E7%A0%81%20%2B%20prefill%20%E7%9B%B8%E5%8A%A0%3Cbr%2F%3EViT%20%E4%B8%8E%20decode%20%E6%8A%A2%E5%90%8C%E4%B8%80%E6%89%B9%20SM%22%5D%0A%20%20S%20--%3E%7C%22%E5%88%86%E6%B1%A0%20%2F%20%E9%87%8D%E5%8F%A0%22%7C%20OVR%5B%22%E5%88%86%E8%AF%8D%E4%B8%8E%E5%89%8D%E7%BC%80%20KV%20%E5%B9%B6%E8%A1%8C%E5%87%86%E5%A4%87%3Cbr%2F%3E%E7%BC%96%E7%A0%81%E6%89%B9%E4%B8%8E%20token%20%E6%89%B9%E4%B9%8B%E9%97%B4%E6%8E%92%E9%98%9F%22%5D%0A%20%20SER%20--%3E%20BAD%5B%22%E6%AD%A3%E5%9C%A8%E5%90%90%E8%AF%8D%E7%9A%84%E7%94%A8%E6%88%B7%E8%A2%AB%3Cbr%2F%3E%E4%B8%80%E5%BC%A0%E5%9B%BE%E7%9A%84%20ViT%20%E6%8C%A1%E4%BD%8F%22%5D%0A%20%20OVR%20--%3E%20GOOD%5B%22decode%20%E5%B8%A6%E5%AE%BD%E5%9E%8B%E5%B7%A5%E4%BD%9C%3Cbr%2F%3E%E4%B8%8D%E8%A2%AB%E7%AE%97%E5%8A%9B%E5%9E%8B%20ViT%20%E6%8C%A4%E5%8D%A0%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在 CPU 上跑大 ViT 还期待与 GPU LLM 流水（除非刻意端侧）。不要把编码器权重与 LLM 权重轮流换入同一张显存不够的卡而不算换入延迟。下一课：没有自回归的嵌入 / 重排服务，批处理画像又不同。</p><p><span class="marginnote">常见误区：容易按「一张图 = 固定 256 token」估容量。动态分辨率（AnyRes / 切块）下，高分辨率图的 \\(n_v\\) 可以是低分辨率图的数倍，批内请求形状参差；会计与调度必须用实际 \\(n_v\\)，否则 KV 容量与定价都会系统性低估高分辨率流量。</span></p><p>出处：Radford et al., CLIP；Liu et al., LLaVA。服务调度是工程延伸，不发明论文号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视觉编码与 LLM prefill 是两段；串行 TTFT 是相加。</li><li>\\(n_v\\) 进入 KV 与二次注意力；分辨率是容量旋钮。</li><li>编码器应与 decode 分池或至少分流。</li><li>文本分词可与编码重叠。</li><li>定价要为每图 / 每视觉 token 分列。</li><li>下一课：嵌入与重排模型服务。</li><li>出处：Radford et al., CLIP；Liu et al., LLaVA。</li></ul>',6))])}const D=d(B,[["render",L]]);export{h as __pageData,D as default};
